window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6547b3186e036ae2"]={"versions": [{"id": "FIG-6547b3186e036ae2", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Ordnungsdiagramm für das Synchronisationskonzept des AUTOSAR Classic Platform Operating System (AUTOSAR OS). Das Diagramm visualisiert die statische Belegungsreihenfolge (Spinlock-Ordnung) einer Menge von Spinlocks zur Deadlock-Prävention bei parallelem Zugriff durch mehrere Tasks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Tasks</strong>: <code>TASK 1</code> und <code>TASK 2</code> (grau hinterlegte Blöcke) als Ausführungseinheiten, die konkurrierend auf gemeinsame Ressourcen zugreifen.\n</li><li><strong>Spinlocks</strong>: Sequenz von sechs Spinlock-Instanzen <code>S1</code>, <code>S2</code>, <code>S3</code>, <code>S4</code>, <code>S5</code> und <code>S6</code> (hellblau hinterlegte Blöcke).\n</li><li><strong>Beziehungsrelationen / Kantenarten (Legende)</strong>:\n<ul class=\"fig-list\"><li><code>Configured order</code>: Blockpfeile mit Kontur zur Definition der statisch konfigurierten Gesamtordnung (<code>S1</code> -&gt; <code>S2</code> -&gt; <code>S3</code> -&gt; <code>S4</code> -&gt; <code>S5</code> -&gt; <code>S6</code>).\n</li><li><code>Allowed effective order</code>: Gestrichelte schwarze Pfeile für zulässige Zugriffs- und Belegungsübergänge.\n</li><li><code>Disallowed effective order</code>: Rot gestrichelter/strichpunktierter Pfeil für unzulässige Rückwärtsbelegungen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><code>TASK 1</code> beginnt die Allokation bei <code>S2</code> und kann sukzessive vorwärts entlang der konfigurierten Ordnung weitere Spinlocks akquirieren (<code>S2</code> -&gt; <code>S3</code>, <code>S3</code> -&gt; <code>S4</code>, <code>S4</code> -&gt; <code>S5</code>).\n</li><li><code>TASK 2</code> startet bei <code>S1</code> und darf ebenfalls entlang der definierten Richtung vorwärtsschreiten (<code>S1</code> -&gt; <code>S2</code>, <code>S2</code> -&gt; <code>S4</code> unter Überspringen von <code>S3</code>, sowie <code>S4</code> -&gt; <code>S6</code> unter Überspringen von <code>S5</code>).\n</li><li>Das Überspringen intermediärer Spinlocks ist zulässig, solange die monotone Vorwärtsrichtung der konfigurierten Reihenfolge gewahrt bleibt.\n</li><li>Ein inverser Belegungsversuch von <code>S6</code> zurück auf <code>S5</code> stellt eine verletzende Rückwärtskante dar (<code>Disallowed effective order</code>) und ist untersagt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm konkretisiert die AUTOSAR-OS-Anforderung zur Vermeidung von Deadlocks (Livelocks/ABBA-Deadlocks) bei verschachtelter Spinlock-Nutzung über eine globale lineare Allokationsreihenfolge.\n</li><li>Ein Task darf nach dem Halten eines Spinlocks nur solche weiteren Spinlocks anfordern, die in der konfigurierten Ordnung echt nachfolgen.\n</li><li>Rückwärtige Anforderungen (<code>S6</code> -&gt; <code>S5</code>) verletzen die OS-Spezifikation und führen bei aktivierter Überwachung zu einem Laufzeitfehler (z. B. Rückgabe eines Fehlerstatus wie <code>E_OS_STATE</code> oder Auslösen eines Protection Hooks).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b880e99f9fae5315", "releases": ["R4.1.3", "R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Ordnungsdiagramm für das Synchronisationskonzept des AUTOSAR Classic Platform Operating System (AUTOSAR OS). Das Diagramm visualisiert die statische Belegungsreihenfolge (Spinlock-Ordnung) einer Menge von Spinlocks zur Deadlock-Prävention bei parallelem Zugriff durch mehrere Tasks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Tasks</strong>: <code>TASK 1</code> und <code>TASK 2</code> (grau hinterlegte Blöcke) als Ausführungseinheiten, die konkurrierend auf gemeinsame Ressourcen zugreifen.\n</li><li><strong>Spinlocks</strong>: Sequenz von sechs Spinlock-Instanzen <code>S1</code>, <code>S2</code>, <code>S3</code>, <code>S4</code>, <code>S5</code> und <code>S6</code> (hellblau hinterlegte Blöcke).\n</li><li><strong>Beziehungsrelationen / Kantenarten (Legende)</strong>:\n<ul class=\"fig-list\"><li><code>Configured order</code>: Blockpfeile mit Kontur zur Definition der statisch konfigurierten Gesamtordnung (<code>S1</code> -&gt; <code>S2</code> -&gt; <code>S3</code> -&gt; <code>S4</code> -&gt; <code>S5</code> -&gt; <code>S6</code>).\n</li><li><code>Allowed effective order</code>: Gestrichelte schwarze Pfeile für zulässige Zugriffs- und Belegungsübergänge.\n</li><li><code>Disallowed effective order</code>: Rot gestrichelter/strichpunktierter Pfeil für unzulässige Rückwärtsbelegungen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><code>TASK 1</code> beginnt die Allokation bei <code>S2</code> und kann sukzessive vorwärts entlang der konfigurierten Ordnung weitere Spinlocks akquirieren (<code>S2</code> -&gt; <code>S3</code>, <code>S3</code> -&gt; <code>S4</code>, <code>S4</code> -&gt; <code>S5</code>).\n</li><li><code>TASK 2</code> startet bei <code>S1</code> und darf ebenfalls entlang der definierten Richtung vorwärtsschreiten (<code>S1</code> -&gt; <code>S2</code>, <code>S2</code> -&gt; <code>S4</code> unter Überspringen von <code>S3</code>, sowie <code>S4</code> -&gt; <code>S6</code> unter Überspringen von <code>S5</code>).\n</li><li>Das Überspringen intermediärer Spinlocks ist zulässig, solange die monotone Vorwärtsrichtung der konfigurierten Reihenfolge gewahrt bleibt.\n</li><li>Ein inverser Belegungsversuch von <code>S6</code> zurück auf <code>S5</code> stellt eine verletzende Rückwärtskante dar (<code>Disallowed effective order</code>) und ist untersagt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm konkretisiert die AUTOSAR-OS-Anforderung zur Vermeidung von Deadlocks (Livelocks/ABBA-Deadlocks) bei verschachtelter Spinlock-Nutzung über eine globale lineare Allokationsreihenfolge.\n</li><li>Ein Task darf nach dem Halten eines Spinlocks nur solche weiteren Spinlocks anfordern, die in der konfigurierten Ordnung echt nachfolgen.\n</li><li>Rückwärtige Anforderungen (<code>S6</code> -&gt; <code>S5</code>) verletzen die OS-Spezifikation und führen bei aktivierter Überwachung zu einem Laufzeitfehler (z. B. Rückgabe eines Fehlerstatus wie <code>E_OS_STATE</code> oder Auslösen eines Protection Hooks).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0f954333478de1fd", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Ordnungsdiagramm für das Synchronisationskonzept des AUTOSAR Classic Platform Operating System (AUTOSAR OS). Das Diagramm visualisiert die statische Belegungsreihenfolge (Spinlock-Ordnung) einer Menge von Spinlocks zur Deadlock-Prävention bei parallelem Zugriff durch mehrere Tasks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Tasks</strong>: <code>TASK 1</code> und <code>TASK 2</code> (grau hinterlegte Blöcke) als Ausführungseinheiten, die konkurrierend auf gemeinsame Ressourcen zugreifen.\n</li><li><strong>Spinlocks</strong>: Sequenz von sechs Spinlock-Instanzen <code>S1</code>, <code>S2</code>, <code>S3</code>, <code>S4</code>, <code>S5</code> und <code>S6</code> (hellblau hinterlegte Blöcke).\n</li><li><strong>Beziehungsrelationen / Kantenarten (Legende)</strong>:\n<ul class=\"fig-list\"><li><code>Configured order</code>: Blockpfeile mit Kontur zur Definition der statisch konfigurierten Gesamtordnung (<code>S1</code> -&gt; <code>S2</code> -&gt; <code>S3</code> -&gt; <code>S4</code> -&gt; <code>S5</code> -&gt; <code>S6</code>).\n</li><li><code>Allowed effective order</code>: Gestrichelte schwarze Pfeile für zulässige Zugriffs- und Belegungsübergänge.\n</li><li><code>Disallowed effective order</code>: Rot gestrichelter/strichpunktierter Pfeil für unzulässige Rückwärtsbelegungen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><code>TASK 1</code> beginnt die Allokation bei <code>S2</code> und kann sukzessive vorwärts entlang der konfigurierten Ordnung weitere Spinlocks akquirieren (<code>S2</code> -&gt; <code>S3</code>, <code>S3</code> -&gt; <code>S4</code>, <code>S4</code> -&gt; <code>S5</code>).\n</li><li><code>TASK 2</code> startet bei <code>S1</code> und darf ebenfalls entlang der definierten Richtung vorwärtsschreiten (<code>S1</code> -&gt; <code>S2</code>, <code>S2</code> -&gt; <code>S4</code> unter Überspringen von <code>S3</code>, sowie <code>S4</code> -&gt; <code>S6</code> unter Überspringen von <code>S5</code>).\n</li><li>Das Überspringen intermediärer Spinlocks ist zulässig, solange die monotone Vorwärtsrichtung der konfigurierten Reihenfolge gewahrt bleibt.\n</li><li>Ein inverser Belegungsversuch von <code>S6</code> zurück auf <code>S5</code> stellt eine verletzende Rückwärtskante dar (<code>Disallowed effective order</code>) und ist untersagt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm konkretisiert die AUTOSAR-OS-Anforderung zur Vermeidung von Deadlocks (Livelocks/ABBA-Deadlocks) bei verschachtelter Spinlock-Nutzung über eine globale lineare Allokationsreihenfolge.\n</li><li>Ein Task darf nach dem Halten eines Spinlocks nur solche weiteren Spinlocks anfordern, die in der konfigurierten Ordnung echt nachfolgen.\n</li><li>Rückwärtige Anforderungen (<code>S6</code> -&gt; <code>S5</code>) verletzen die OS-Spezifikation und führen bei aktivierter Überwachung zu einem Laufzeitfehler (z. B. Rückgabe eines Fehlerstatus wie <code>E_OS_STATE</code> oder Auslösen eines Protection Hooks).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6547b3186e036ae2", "to": "FIG-b880e99f9fae5315", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b880e99f9fae5315", "to": "FIG-0f954333478de1fd", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
